(function() {
  angular.module('gawsis').service('Application', [
    '$location', 'CONSTANTS', function($location, CONSTANTS) {
      var currentApp, program, programMap, wmoLink;
      currentApp = null;
      program = null;
      wmoLink = null;
      programMap = {
        'gos.html': {
          id: 4,
          name: 'GOS'
        }
      };
      return {
        GAWSIS: 'GAWSIS',
        OSCAR: 'OSCAR',
        GAWSIS_ID: 1,
        AMDAR_ID: 1000,
        ADS_C_ID: 1001,
        GOS: 'GOS',
        getCurrent: function() {
          var location, page, programObject;
          if (currentApp == null) {
            location = $location.absUrl().substring(0, $location.absUrl().lastIndexOf($location.url()));
            if (location.lastIndexOf(this.GAWSIS) > location.lastIndexOf(this.OSCAR)) {
              currentApp = this.GAWSIS;
            } else {
              currentApp = this.OSCAR;
              for (page in programMap) {
                programObject = programMap[page];
                if (location.indexOf(page) > -1) {
                  program = programObject;
                }
              }
            }
          }
          return currentApp;
        },
        getProgram: function() {
          if (program == null) {
            this.getCurrent();
          }
          return program;
        },
        debugLogger: function(logString, logObject) {
          if (CONSTANTS.ENABLE_DEBUG) {
            if (logObject) {
              return console.debug('DEBUG: ' + logString, logObject);
            } else {
              return console.debug('DEBUG: ' + logString);
            }
          }
        },
        getWmoMapLink: function() {
          if (currentApp === this.OSCAR) {
            wmoLink = "https://oscar.wmo.int/surface/#/about";
          } else {
            wmoLink = "https://gawsis.meteoswiss.ch/GAWSIS/#/about";
          }
          return wmoLink;
        }
      };
    }
  ]);

}).call(this);


