(function() {
  angular.module('gawsis').controller('EditProfileCtrl', [
    '$scope', '$state', '$stateParams', 'AdministrationHttpService', 'QFormValidation', 'dialogs', 'growl', '$q', function($scope, $state, $stateParams, AdministrationHttpService, QFormValidation, dialogs, growl, $q) {
      $scope.editProfile = true;
      $scope.editForm = false;
      $scope.user = {};
      $scope.userId = $stateParams.userId;
      $scope.onFormLoad = function() {
        var deferred, success;
        deferred = $q.defer();
        AdministrationHttpService.getUser($stateParams.userId).then(success = function(result) {
          $scope.user = result.data;
          if ($scope.user.id === null) {
            $scope.user.registerAsContact = false;
          } else if ($scope.user.id == null) {
            $scope.user.registerAsContact = false;
          } else {
            $scope.user.registerAsContact = true;
          }
          return deferred.resolve();
        });
        return deferred.promise;
      };
      $scope.save = function() {
        var error, success;
        $scope.user.editProfile = true;
        if ($scope.user.registerAsContact === true) {
          return AdministrationHttpService.updateUserContact($stateParams.userId, $scope.user).then(success = function(response) {
            growl.success('The user profile was updated successfully.');
            return $state.go('home');
          }, error = function(response) {
            return QFormValidation.renderFormErrors($scope, $scope.userForm, response);
          });
        } else {
          return AdministrationHttpService.updateUser($stateParams.userId, $scope.user).then(success = function(response) {
            growl.success('The user profile was updated successfully.');
            return $state.go('home');
          }, error = function(response) {
            return QFormValidation.renderFormErrors($scope, $scope.userForm, response);
          });
        }
      };
      return $scope.cancel = function() {
        var response;
        if ($scope.userForm.$dirty) {
          response = dialogs.confirm('Unsaved changes', 'You have unsaved changes. Are you sure you wish to leave this page? Your changes will be lost.', {
            backdrop: 'static',
            size: 'sm'
          });
          response.result.then(function(result) {
            return $state.go('home');
          });
        } else {
          $state.go('home');
        }
      };
    }
  ]);

}).call(this);


