(function() {
  angular.module('gawsis').controller('AbosTerritoryViewCtrl', [
    '$rootScope', '$scope', '$state', '$stateParams', 'dialogs', 'growl', 'ngTableParams', '$modal', function($rootScope, $scope, $state, $stateParams, dialogs, growl, ngTableParams, $modal) {
      $scope.abosProgramme = {};
      $scope.territoriesTableParams = new ngTableParams({
        page: 1,
        count: 2,
        total: 1,
        sorting: {
          validSince: 'desc'
        }
      }, {
        counts: []
      });
      $scope.addTerritory = function() {
        var abosProgrammeTerritoryModal;
        abosProgrammeTerritoryModal = $modal.open({
          templateUrl: 'views/management/referencedata/abos/abosProgramme/abosProgrammeParts/abosTerritoryForm.html',
          controller: 'AbosTerritoryFormCtrl',
          backdrop: 'static',
          resolve: {
            usedTerritories: function() {
              return $scope.abosProgramme.territories;
            },
            edit: function() {
              return false;
            }
          }
        });
        abosProgrammeTerritoryModal.result.then(function(response) {
          $rootScope.unbindEvents();
          if (response != null) {
            if ($scope.abosProgramme.territories == null) {
              $scope.abosProgramme.territories = [];
            }
            $scope.abosProgramme.territories.push(response);
            $scope.abosProgrammeForm.territories.$setViewValue($scope.abosProgrammeForm.territories.$viewValue);
            return angular.element('#characteristicsHeading').removeClass('has-error');
          }
        });
      };
      $scope.deleteTerritory = function(territory) {
        var response;
        response = dialogs.confirm('Delete country/territory', 'Are you sure you wish to delete this country/territory?', {
          backdrop: 'static',
          size: 'sm'
        });
        response.result.then(function(result) {
          $scope.abosProgramme.territories.splice($scope.abosProgramme.territories.indexOf(territory), 1);
          if (territory.id != null) {
            if ($scope.abosProgramme.removedTerritories == null) {
              $scope.abosProgramme.removedTerritories = [];
            }
            $scope.abosProgramme.removedTerritories.push(territory.id);
          }
          $scope.abosProgrammeForm.territories.$setViewValue($scope.abosProgrammeForm.territories.$viewValue);
          return angular.element('#characteristicsHeading').removeClass('has-error');
        });
      };
    }
  ]);

}).call(this);


