(function() {
  angular.module('gawsis').controller('DocumentListViewCtrl', [
    '$scope', 'dialogs', '$window', 'SERVICES', 'SecuritySrv', 'ngTableParams', '$filter', function($scope, dialogs, $window, SERVICES, SecuritySrv, ngTableParams, $filter) {
      $scope.documentTableParams = new ngTableParams({
        page: 1,
        count: 10,
        sorting: {
          title: "desc"
        }
      }, {
        counts: [],
        total: 1,
        getData: function($defer, params) {
          var orderedData;
          if ($scope.station.documents != null) {
            params.total($scope.station.documents.length);
            params.count($scope.station.documents.length);
            orderedData = (params.sorting() ? $filter("orderBy")($scope.station.documents, params.orderBy()) : $scope.station.documents);
            $defer.resolve(orderedData.slice((params.page() - 1) * params.count(), params.page() * params.count()));
          }
        }
      });
      $scope.downloadDocument = function(document) {
        var downloadUrl;
        downloadUrl = SERVICES._PREFIX + SERVICES.FILES._ROOT + SERVICES.FILES.DOWNLOAD;
        if (document.id != null) {
          downloadUrl = downloadUrl + SERVICES.FILES.DOCUMENT + '/' + document.id;
        } else {
          downloadUrl = downloadUrl + SERVICES.FILES.TEMP_DOCUMENT + '/' + document.fileId + '?ticket=' + window.encodeURIComponent(JSON.stringify(SecuritySrv.getUser().ticket));
        }
        $window.location = downloadUrl;
      };
      $scope.deleteDocument = function(document) {
        var response;
        response = dialogs.confirm('Delete document', 'You are about to permanently delete metadata information that cannot be restored. Are you sure you wish to delete this document?', {
          backdrop: 'static',
          size: 'sm'
        });
        response.result.then(function(result) {
          $scope.station.documents.splice($scope.station.documents.indexOf(document), 1);
          if (document.id != null) {
            if ($scope.station.removedDocuments == null) {
              $scope.station.removedDocuments = [];
            }
            return $scope.station.removedDocuments.push(document.id);
          }
        });
      };
    }
  ]);

}).call(this);


