(function() {
  angular.module('gawsis').controller('ViewContactCtrl', [
    '$scope', '$state', '$stateParams', 'ContactHttpService', 'AdministrationHttpService', '$window', 'SERVICES', 'dialogs', 'growl', '$q', 'CONSTANTS', 'SecuritySrv', function($scope, $state, $stateParams, ContactHttpService, AdministrationHttpService, $window, SERVICES, dialogs, growl, $q, CONSTANTS, SecuritySrv) {
      var success;
      ContactHttpService.getContactAndStationStatus($stateParams.contactId).then(success = function(result) {
        var promises, securityPromiseDeactivateContacts, territorySuffix;
        $scope.contactDTO = result.data;
        if ($scope.contactDTO.address != null) {
          $scope.addressParts = $scope.contactDTO.address.split('\n');
        }
        if ($scope.permissions['G_MANAGE_USERS']) {
          return $scope.canDeactivateContacts = true;
        } else {
          promises = [];
          territorySuffix = CONSTANTS.TERRITORY_OBJECT_ID_PREFIX + $scope.contactDTO.countryId;
          securityPromiseDeactivateContacts = SecuritySrv.resolvePermission('G_DEACTIVATE_CONTACTS', territorySuffix);
          promises.push(securityPromiseDeactivateContacts);
          securityPromiseDeactivateContacts.then(success = function(response) {
            if ($scope.permissions['G_DEACTIVATE_CONTACTS' + '_' + territorySuffix]) {
              return $scope.canDeactivateContacts = true;
            }
          });
          return $q.all(promises);
        }
      });
      $scope.downloadContact = function(filetype) {
        var downloadUrl;
        downloadUrl = SERVICES._PREFIX + SERVICES.CONTACTS._ROOT + SERVICES.CONTACTS.DOWNLOAD + SERVICES.CONTACTS.CONTACT + '/' + $stateParams.contactId + '/' + filetype;
        $window.location = downloadUrl;
      };
      $scope["delete"] = function() {
        var contactName;
        if ($scope.contactDTO.title != null) {
          contactName = $scope.contactDTO.title + ' ' + $scope.contactDTO.name + ' ' + $scope.contactDTO.surname;
        } else {
          contactName = $scope.contactDTO.name + ' ' + $scope.contactDTO.surname;
        }
        AdministrationHttpService.singleStationContact($scope.contactDTO.id).then(success = function(result) {
          var response;
          if (result.data.toString() !== '') {
            response = dialogs.confirm('Remove contact', 'This contact is the last contact for Station(s) ' + result.data + '. After removal, the station can only be edited by an administrator or the responsible Program or National focal points. Are you sure you want to proceed deleting it?', {
              backdrop: 'static',
              size: 'sm'
            });
            return response.result.then(function(result) {
              return ContactHttpService.deleteContact($scope.contactDTO.userId).then(success = function(result) {
                growl.success('The contact was removed successfully.');
                $state.go('myContacts-view', {}, {
                  reload: true
                });
              });
            });
          } else {
            response = dialogs.confirm('Remove contact', 'Are you sure you wish to remove "' + contactName + '" contact?', {
              backdrop: 'static',
              size: 'sm'
            });
            return response.result.then(function(result) {
              return ContactHttpService.deleteContact($scope.contactDTO.userId).then(success = function(result) {
                growl.success('The contact was removed successfully.');
                $state.go('myContacts-view', {}, {
                  reload: true
                });
              });
            });
          }
        });
      };
      return $scope.deactivate = function() {
        var contactFullName, response;
        contactFullName = '';
        if ($scope.contactDTO.title != null) {
          contactFullName = $scope.contactDTO.title + ' ';
        }
        contactFullName = contactFullName + $scope.contactDTO.name + ' ' + $scope.contactDTO.surname;
        response = dialogs.confirm('Deactivate contact', 'Are you sure you want to deactivate contact ' + contactFullName + '? The contact will be removed as station contact and no longer be visible in the application.', {
          backdrop: 'static',
          size: 'sm'
        });
        return response.result.then(function(result) {
          return ContactHttpService.deactivateContact($scope.contactDTO.id).then(success = function(result) {
            growl.success('The contact was deactivated successfully.');
            $state.go('myContacts-view', {}, {
              reload: true
            });
          });
        });
      };
    }
  ]);

}).call(this);


