(function() {
  angular.module('gawsis').controller('ScheduleViewCtrl', [
    '$rootScope', '$scope', '$state', '$stateParams', '$modal', 'dialogs', 'growl', 'ngTableParams', 'QFormValidation', 'StationService', function($rootScope, $scope, $state, $stateParams, $modal, dialogs, growl, ngTableParams, QFormValidation, StationService) {
      if ($scope.dataGeneration != null) {
        StationService.setTimeMinutesDateFieldsOfSchedule($scope.dataGeneration);
      }
      return $scope.generateCombinedDiurnalBaseDescription = function(schedule) {
        var combinedDiurnalBaseDescription;
        combinedDiurnalBaseDescription = '';
        if (schedule.diurnalBaseHour < 10) {
          combinedDiurnalBaseDescription += '0';
        }
        combinedDiurnalBaseDescription += schedule.diurnalBaseHour + ':';
        if (schedule.diurnalBaseMinute < 10) {
          combinedDiurnalBaseDescription += '0';
        }
        combinedDiurnalBaseDescription += schedule.diurnalBaseMinute;
        return combinedDiurnalBaseDescription;
      };
    }
  ]);

}).call(this);


