(function() {
  angular.module('gawsis').controller('PhotoCarouselViewCtrl', [
    '$rootScope', '$scope', '$state', '$modal', '$modalInstance', 'photos', 'selectedPhoto', 'title', 'SecuritySrv', 'editable', 'approvalStatusId', 'CONSTANTS', 'dialogs', 'growl', 'MODAL_CLASSES', 'couldDeleteStationData', function($rootScope, $scope, $state, $modal, $modalInstance, photos, selectedPhoto, title, SecuritySrv, editable, approvalStatusId, CONSTANTS, dialogs, growl, MODAL_CLASSES, couldDeleteStationData) {
      var photo, splitParts, _i, _len, _ref;
      $scope.title = title;
      $scope.photos = photos;
      $scope.editable = editable;
      $scope.approvalStatusId = approvalStatusId;
      $scope.draftStatusId = CONSTANTS.APPROVAL_STATUS_DRAFT_ID;
      $scope.couldDeleteStationData = couldDeleteStationData;
      $scope.isCopy = $state.params.isCopy;
      $rootScope.bindEvents(MODAL_CLASSES.PHOTO_CAROUSEL);
      if ((SecuritySrv.getUser() != null) && (SecuritySrv.getUser().ticket != null)) {
        $scope.ticket = window.encodeURIComponent(JSON.stringify(SecuritySrv.getUser().ticket));
      }
      _ref = $scope.photos;
      for (_i = 0, _len = _ref.length; _i < _len; _i++) {
        photo = _ref[_i];
        if (photo.filename != null) {
          splitParts = photo.filename.split('.');
          if (splitParts.length > 1) {
            photo.filetype = splitParts[splitParts.length - 1];
          }
        }
        if (photo === selectedPhoto) {
          photo.active = true;
        } else {
          photo.active = false;
        }
      }
      $scope["delete"] = function(photo) {
        var response;
        response = dialogs.confirm('Delete photo', 'You are about to permanently delete metadata information that cannot be restored. Are you sure you wish to delete this photo?', {
          backdrop: 'static',
          size: 'sm'
        });
        return response.result.then(function(result) {
          $scope.photos.splice($scope.photos.indexOf(photo), 1);
          if ((photo.id != null)) {
            return $modalInstance.close(photo.id);
          } else {
            return $modalInstance.close(null);
          }
        });
      };
      $rootScope.setSizeOfModal(MODAL_CLASSES.PHOTO_CAROUSEL);
    }
  ]);

}).call(this);


