(function() {
  angular.module('gawsis').controller('WigosIdViewCtrl', [
    '$rootScope', '$scope', '$state', '$stateParams', 'dialogs', 'growl', 'ngTableParams', '$modal', 'MODAL_CLASSES', '$filter', 'StationHttpService', function($rootScope, $scope, $state, $stateParams, dialogs, growl, ngTableParams, $modal, MODAL_CLASSES, $filter, StationHttpService) {
      var getMostRecentTerritoryId;
      $scope.wigosIdsTableParams = new ngTableParams({
        page: 1,
        count: 2,
        total: 1
      }, {
        counts: []
      });
      $scope.addWigosId = function() {
        var success;
        StationHttpService.getWigosIdBlockTwoList(getMostRecentTerritoryId()).then(success = function(response) {
          var wigosIdModal;
          wigosIdModal = $modal.open({
            templateUrl: 'views/management/stations/stationFormParts/wigosIdForm.html',
            controller: 'WigosIdFormCtrl',
            windowClass: MODAL_CLASSES.WIGOS_ID,
            backdrop: 'static',
            resolve: {
              wigosId: function() {
                return {};
              },
              usedWigosIds: function() {
                return $scope.station.wigosIds;
              },
              edit: function() {
                return false;
              },
              wigosIdpartTwoList: function() {
                return response.data;
              },
              disableWigosIdpartTwo: function() {
                return response.data.length === 1;
              }
            }
          });
          return wigosIdModal.result.then(function(response) {
            $rootScope.unbindEvents();
            if (response != null) {
              if ($scope.station.wigosIds == null) {
                $scope.station.wigosIds = [];
              }
              if ($scope.station.wigosIds.length === 0) {
                response.primary = true;
              }
              $scope.station.wigosIds.push(response);
              $scope.stationForm.wigosIds.$setDirty();
              return $rootScope.removeHasErrorFromAccordion('characteristicsHeading', 'stationCharacteristics');
            }
          });
        });
      };
      getMostRecentTerritoryId = function() {
        var sortedListOfTerritories;
        sortedListOfTerritories = $filter('orderBy')(angular.copy($scope.station.territories), 'validSince');
        return sortedListOfTerritories[sortedListOfTerritories.length - 1].territoryId;
      };
      $scope.editWigosId = function(wigosId) {
        var success;
        StationHttpService.getWigosIdBlockTwoList(getMostRecentTerritoryId(), wigosId.wid).then(success = function(response) {
          var wigosIdModal;
          wigosIdModal = $modal.open({
            templateUrl: 'views/management/stations/stationFormParts/wigosIdForm.html',
            controller: 'WigosIdFormCtrl',
            windowClass: MODAL_CLASSES.WIGOS_ID,
            backdrop: 'static',
            resolve: {
              wigosId: function() {
                return wigosId;
              },
              usedWigosIds: function() {
                return $scope.station.wigosIds;
              },
              edit: function() {
                return true;
              },
              wigosIdpartTwoList: function() {
                return response.data;
              },
              disableWigosIdpartTwo: function() {
                return response.data.length === 1;
              }
            }
          });
          return wigosIdModal.result.then(function(response) {
            $rootScope.unbindEvents();
            $scope.stationForm.wigosIds.$setDirty();
            return $rootScope.removeHasErrorFromAccordion('characteristicsHeading', 'stationCharacteristics');
          });
        });
      };
      $scope.deleteWigosId = function(wigosId) {
        var response;
        response = dialogs.confirm('Delete WIGOS Station Identifier', 'You are about to permanently delete metadata information that cannot be restored. Are you sure you wish to delete this WIGOS Station Identifier?', {
          backdrop: 'static',
          size: 'sm'
        });
        response.result.then(function(result) {
          $scope.station.wigosIds.splice($scope.station.wigosIds.indexOf(wigosId), 1);
          if (wigosId.id != null) {
            if ($scope.station.removedWigosIds == null) {
              $scope.station.removedWigosIds = [];
            }
            $scope.station.removedWigosIds.push(wigosId.id);
          }
          return $rootScope.removeHasErrorFromAccordion('characteristicsHeading', 'stationCharacteristics');
        });
      };
      $scope.updateWigosIdPrimary = function(position, wigosIds) {
        return angular.forEach(wigosIds, function(wigosId, index) {
          if (position !== index) {
            return wigosId.primary = false;
          }
        });
      };
    }
  ]);

}).call(this);


