(function() {
  angular.module('gawsis').controller('ListXmlCtrl', [
    '$scope', '$state', 'ngTableParams', 'StationHttpService', 'SERVICES', '$window', function($scope, $state, ngTableParams, StationHttpService, SERVICES, $window) {
      var success;
      $scope.totalDisplayed = 1000;
      $scope.visible = false;
      $scope.loadMore = function() {
        $scope.totalDisplayed += 1000;
        if ($scope.xml.length <= $scope.totalDisplayed) {
          return $scope.visible = false;
        }
      };
      return StationHttpService.getXmlFilenames().then(success = function(result) {
        $scope.xml = result.data;
        return $scope.visible = true;
      });
    }
  ]);

}).call(this);


