(function() {
  angular.module('gawsis').filter('decimals', function() {
    return function(input, numOfDigits, maxNumOfDigits) {
      var decimals, difference, i, idx, out, parts;
      if (input !== 0) {
        input = input || '';
      }
      out = '';
      input = input.toString();
      decimals = input.length - input.indexOf('.') - 1;
      difference = numOfDigits - decimals;
      idx = input.indexOf('.');
      if (input !== '') {
        if (numOfDigits) {
          out = input;
          if (idx < 0) {
            out = out + '.';
            difference = numOfDigits;
          }
          i = 0;
          while (i < difference) {
            out = out + 0;
            i++;
          }
        }
        if (maxNumOfDigits != null) {
          parts = out.split('.');
          out = parts[0] + '.' + parts[1].substr(0, maxNumOfDigits);
        }
      }
      return out;
    };
  });

}).call(this);


