(function() {
  require(['esri/map', 'esri/geometry/Extent', 'esri/layers/WebTiledLayer', 'esri/layers/FeatureLayer', 'dojo/domReady!', 'esri/lang', 'dojo/dom-style', 'dijit/TooltipDialog', 'dijit/popup', 'esri/tasks/IdentifyTask', 'esri/tasks/IdentifyParameters', 'esri/layers/ArcGISTiledMapServiceLayer', 'dojo/on', 'esri/geometry/webMercatorUtils', 'esri/SpatialReference', 'esri/geometry/Point', 'esri/dijit/Scalebar'], function() {
    angular.bootstrap(document.documentElement, ['gawsis']);
  });

}).call(this);

var esriMap = angular.module('esriSupport', []);

esriMap
.controller("ESRIMapController",
	["$rootScope", "$scope", "$attrs", "Application", "StationHttpService",
		"$location", "$anchorScroll", 'CONSTANTS',
		function ($rootScope, $scope, $attrs, Application, StationHttpService,
			$location, $anchorScroll, CONSTANTS) {
			var self = this; // Reference to 'this' to use in functions
			var mapDiv = [];
			var featureLayers = [];
			var tiledLayers = [];
			var graphicsLayers = [];
			var dynamicLayers = [];
			var map;

			//Init function to be called so as to initialize the map
			this.init = function (element) {
				// Perform checks regarding the validity of the requested map.
				if (!$attrs.id) {
					throw new Error("An id is required for a map.");
				}
				if (document.getElementById($attrs.id + "_div")) {
					throw new Error(
						"There is already a map with id " + $attrs.id
						+ " defined in the current page.");
				}
				self.$element = element;
				// Create a div to host the map.
				mapDiv = document.createElement('div');
				mapDiv.setAttribute('id', $attrs.id + "_div");
				self.$element.append(mapDiv);
				if ($attrs.mapHeight) {
					$("#" + $attrs.id + "_div").css({
						"height": $attrs.mapHeight + "px"
					});
				}
				if ($attrs.mapWidth) {
					$("#" + $attrs.id + "_div").css({
						"width": $attrs.mapWidth + "px"
					});
				}
				// Create the map container.
				// TODO support creating a map without a basemap
				var mapProperties = {
					center: $attrs.center ? JSON.parse($attrs.center)
						: [-56.049, 38.485],
					zoom: $attrs.zoom ? parseInt($attrs.zoom) : 2,
					nav: $attrs.nav ? Boolean($attrs.nav) : false,
					maxZoom: $attrs.maxzoom ? parseInt($attrs.maxzoom) : 12,
					minZoom: $attrs.minzoom ? parseInt($attrs.minzoom) : 1,
					autoResize: true,
					logo: false,
					attributionWidth: $attrs.attributionWidth ? $attrs.attributionWidth : 0.45, 
					fitExtent: true,
					maxZoom: $attrs.maxzoom ? parseInt($attrs.maxzoom) : 12,
				}

				// dynamically specify the height of the map if it is passed as and html attribute
				if ($attrs.id) {
					$scope.map = new esri.Map($attrs.id + "_div",
						mapProperties);
					if ($attrs.mapHeight || $attrs.mapWidth) {
						var data = {}
						if ($attrs.mapHeight) {
							data.height = parseInt($attrs.mapHeight);
						}
						if ($attrs.mapWidth) {
							data.width = parseInt($attrs.mapWidth);
						}
						data.mapDivID = $attrs.id + '_div';
						data.expandedMap = true;
						resizeMap(data)
					}
					// initialize the map extent
					$scope.validExtent = $scope.map.extent
				}

				// A scalebar is added on the map in case it is required
				if ($attrs.scalebar == 'true') {
					$scope.scalebar = new esri.dijit.Scalebar({
						map: $scope.map,
						scalebarUnit: "metric",
						attachTo: "bottom-left",
						scalebarStyle: "line"
					});
				}

				require(["dojo/on"], function (on) {
					$scope.map.on('load', function (e) {
						console.debug('$scope.map MAP: ', $scope.map);
						$scope.map.reposition();
						$scope.validExtent = e.extent;
						$scope.$emit($attrs.id + "-onload", e);
					});

					$scope.map.on('click', function (e, d) {
						$scope.$emit($attrs.id + "-onclick", e, d);
					});
					var validExtentTimer;

					$scope.map.on('resize', function (e, d) {
						clearTimeout(validExtentTimer);
						validExtentTimer = setTimeout(function () {
							setValidExtent(e.extent, $scope.map)
						}, 600);
						$scope.map.reposition();
						$scope.$emit($attrs.id + "-onresize", e, d);
					});

					var zoomTimer;
					$scope.map.on('zoom-end', function (e, d) {
						var MAX_Y = 20000000;
						// Update the valid extent after the zoom end
						if ((e.extent.ymax < MAX_Y && e.extent.ymin > -MAX_Y)) {
							$scope.validExtent = e.extent;
						}
						$scope.$emit($attrs.id + "-zoomend", e, d);
					});

					$scope.map.on('zoom-start', function (e, d) {
						$scope.$emit($attrs.id + "-zoomstart", e, d);
					});

					$scope.map.on('pan-start', function (e, d) {
						$scope.$emit($attrs.id + "-panstart", e, d);
					});
					$scope.map.on('pan', function (e, d) {
						var MAX_Y = 20000000;
						//store the valid extents in the $scope.validExtent. while panning to valid positions
						if ((e.extent.ymax < MAX_Y && e.extent.ymin > -MAX_Y)) {
							$scope.validExtent = e.extent;
						}
					});

					$scope.map.on('pan-end', function (e, d) {
						var MAX_Y = 20000000;
						// there is a valid extent - and the current extent is out of bounds keep the ymin/max and get the new xmin/max
						if ($scope.validExtent && (e.extent.ymax > MAX_Y
							|| e.extent.ymin < -MAX_Y)) {
							if (!(e.extent.ymax > MAX_Y && e.extent.ymin
								< -MAX_Y)) {
								// accept only the new xmin/xmax and use the ymin and ymax of the previous valid extent
								$scope.validExtent.xmin = e.extent.xmin;
								$scope.validExtent.xmax = e.extent.xmax;
								if ($scope.validExtent && $scope.validExtent
									!= null) {
									$scope.map.setExtent($scope.validExtent,
										false);
								}

							}
						}
						$scope.$emit($attrs.id + "-paned", e, d);
					});

					$scope.map.on('mouse-down', function (e, d) {
						Application.debugLogger("mouse down $scope.map: ",
							$scope.map);
						$scope.map.resize();
						$scope.$emit($attrs.id + "-mousedown", e, d);
					});

					$scope.map.on('mouse-over', function (e, d) {
						$scope.$emit($attrs.id + "-mouseover", e, d);
					});

					$scope.map.on('mouse-move', function (e, d) {
						$scope.$emit($attrs.id + "-mousemove", e, d);
					});

					$scope.map.on('mouse-out', function (e, d) {
						$scope.$emit($attrs.id + "-mouseout", e, d);
					})
					$scope.map.on('layer-add-result', function (e, d) {
						$scope.$emit($attrs.id + "-layer-add-result", e, d);
					});
				});

				// ####################### ADD LAYERS TO THE MAP. #######################
				if (tiledLayers.length > 0) {
					$scope.map.addLayers(tiledLayers);
					tiledLayers = [];
				}
				if (dynamicLayers.length > 0) {
					for (var i = 0; i < dynamicLayers.length; i++) {
						var dlayer = dynamicLayers[i];
						$scope.$emit(dlayer.id + "-layer-load");
						$scope.map.addLayer(dlayer)
					}
					dynamicLayers = [];
				} //end if
				if (graphicsLayers.length > 0) {
					for (var i = 0; i < graphicsLayers.length; i++) {
						var glayer = graphicsLayers[i];
						if (glayer.gpurl) {
							$scope.map.addLayer(glayer.layer)
							$scope.$emit(
								glayer.layer.id + "-service-container-load",
								glayer.gpurl);
						} //end if
						else {
							$scope.map.addLayer(glayer.layer)
							$scope.$emit(
								glayer.layer.id + "-graphics-layer-load");
						} //end else
					} //end for
					graphicsLayers = [];
				}
				// If there are already layers defined for this map, add them now.
				if (featureLayers.length > 0) {
					for (var i = 0; i < featureLayers.length; i++) {
						var flayer = featureLayers[i];
						$scope.$emit(flayer.id + "-layer-load");
						$scope.map.addLayer(flayer)
					}
					featureLayers = [];
				}

				// ####################### MAP DO EVENTS #######################
				$scope.$on($attrs.id + "-do-event", function (event, data) {
					mapDoFunctions(event, data);
				});

				function mapDoFunctions(event, data) {
					switch (data.command) {
						case "exportMap":
							require(["esri/request", "esri/tasks/PrintTask",
									"esri/tasks/PrintParameters",
									"esri/tasks/PrintTemplate",
									"dojo/_base/json", "esri/config",
									"esri/urlUtils"
								],
								function (esriRequest, PrintTask,
									PrintParameters, PrintTemplate, JSON,
									esriConfig, urlUtils) {
									urlUtils.addProxyRule({
										urlPrefix: angular.element(
											"body").scope().properties.mapExportService,
										proxyUrl: "rest/api/download/proxy"
									});

									var format = data.format;
									var layout = "";
									if (Application.getCurrent()
										== Application.GAWSIS) {
										if (data.expandedMap) {
											layout = "GAWSIS A4 Portrait";
										} else {
											layout = "GAWSIS A4 Landscape";
										}
									}

									if (Application.getCurrent()
										== Application.OSCAR) {
										if (data.expandedMap) {
											if (data.isDeclared) {
												layout = "surface A4 Portrait";
											} else {
												layout = "surface A4 Portrait Assessed";
											}
										} else {
											if (data.isDeclared) {
												layout = "surface A4 Landscape";
											} else {
												layout = "surface A4 Landscape Assessed";
											}
										}
									}
									var requestHandle;
									var params = new PrintParameters();
									var template = PrintTemplate();
									template.layout = layout;
									template.format = format;
									params.map = $scope.map;
									params.template = template;
									// Fix for 2.28 upgrade.
									var printTask = new esri.tasks.PrintTask(
										angular.element(
											"body").scope().properties.mapExportService);
									var printDefinition = printTask._getPrintDefinition(
										$scope.map, params);
									var Web_Map_as_JSON = JSON.toJson(printDefinition
										);

									// Timeout is by defaut 60000ms -> 1min
									// To increase add timeout: 120000
									requestHandle = esriRequest({
										url: angular.element(
											"body").scope().properties.mapExportService,
										content: {
											f: 'json',
											Web_Map_as_JSON: Web_Map_as_JSON,
											Format: format,
											Layout_Template: layout
										},
										handleAs: 'json',
										callbackParamName: 'callback',
									}, {
										usePost: true
									});

									requestHandle.then(function (result) {
										Application.debugLogger(
											'success result', result);
										if (data.action == 'download') {
											document.getElementById(
												'downloadIframe').src = "rest/api/download/map?url="
												+ result.results[0].value.url;
											$scope.$emit("spinner");
										} else if (data.action == 'getUrl') {
											$scope.$emit(
												$scope.map.id + "-export-ready",
												result.results[0].value.url);
										}
									}, function (error) {
										Application.debugLogger(
											"Fail result error:", error)
										$scope.$emit("spinner");
										alert(
											'Please retry. Map export was unavailable. ')
										$scope.$emit(
											$scope.map.id + "-export-ready",
											'error');
										throw new Error(error.message);
									});
								});
							break;

						case "show":
							if (!$scope.map.getLayer(data.id).visible) {
								$scope.map.getLayer(data.id).show();
							}
							break;

						case "hide":
							$scope.map.getLayer(data.id).hide();
							break;

						case "setOpacity":
							$scope.map.getLayer(data.id).setOpacity(.50);
							break;

						case "destroy":
							$scope.map.destroy();
							break;
						case "reposition":
							$scope.map.reposition();
							break;
						case "resize":
							$scope.map.resize();
							break;
						case "setZoomFactor":
							$scope.map.setZoom(data.factor);
							break;

						case "createToolbar":
							require(["esri/graphic", "esri/geometry/Extent",
									"esri/toolbars/draw",
									"esri/symbols/SimpleFillSymbol",
									"esri/geometry/webMercatorUtils"],
								function (Graphic, Extent, Draw,
									SimpleFillSymbol, webMercatorUtils) {

									var tb = new Draw($scope.map,
										{showTooltips: false});
									tb.setRespectDrawingVertexOrder(false)
									tb.on("draw-end", drawEnded);
									var shape = eval("Draw." + data.shape)
									tb.activate(shape);

									function drawEnded(evtObj) {
										var geometry = evtObj.geometry;
										$scope.map.graphics.clear();
										var graphic = new Graphic(geometry,
											new SimpleFillSymbol());
										$scope.map.graphics.add(graphic);
										var wgs_84_geometry = webMercatorUtils.webMercatorToGeographic(
											graphic.geometry);
										$scope.$emit("draw-toolbar-draw-ended",
											wgs_84_geometry);
									}
								});
							break;

						case "executeIdentifyTask":
							var event = data.evt;
							// Default/fallback url used for identify tasks in case it is not provided one or if the layer specified to be used
							// Does not exist on the map
							var url = $scope.appProperties.tiledMapServiceUrlPrefix
								+ 'all' + "_declared_" + 'all' + "/MapServer";
							if ($scope.map.getLayer(data.id)) {
								url = $scope.map.getLayer(data.id).url;
							}
							var returnData = {};
							var location = {};
							var myPoint = {};
							var wgs = new esri.SpatialReference({
								'wkid': 102100
							});
							var mercPointGeometry = new esri.geometry.Point(
								parseFloat(event.mapPoint.x),
								parseFloat(event.mapPoint.y), wgs)
							var returnData = {}
							returnData.event = data.evt;
							require(["esri/geometry/webMercatorUtils"],
								function (webMercatorUtils) {
									var wgs84Geometry = webMercatorUtils.webMercatorToGeographic(
										mercPointGeometry);
									location.latitude = wgs84Geometry.y;
									location.longitude = wgs84Geometry.x;
									location.oscarSelections = data.oscarSelections;
									location.resolution = $scope.map.extent.getWidth()
										/ $scope.map.width;

									if (location.oscarSelections != null
										&& location.oscarSelections.length
										> 0) {
										StationHttpService.identifyStations(
											location).then(function (result) {
											if (result.data != "") {
												var feature = {
													STATION_ID: result.data.id,
													STATION_NAME: result.data.name,
													PRIMARY_WIGOS_ID: result.data.primaryWigosId,
													STATION_TYPE_NAME: result.data.typeName,
													STATION_DECLARED_STATUS_NAME: result.data.declaredStatus,
													STATION_ASSESSED_STATUS_NAME: result.data.assessedStatus,
													DATE_ESTABLISHED: result.data.dateEstablished,
													DATE_CLOSED: result.data.dateClosed,
													STATION_PROGRAM_STATUSES: result.data.stationProgramsDeclaredStatuses,
													STATION_PROGRAM_ASSESSED_STATUSES: result.data.stationProgramsAssessedStatuses
												}
												var clickedFeature = {}
												clickedFeature.attributes = feature;
												clickedFeature.pageX = event.pageX;
												clickedFeature.pageY = event.pageY;
												clickedFeature.infoboxTicket = data.infoboxTicket
												returnData.clickedFeature = clickedFeature;

												$scope.$emit("identify-end",
													returnData);
											} else {
												$scope.$emit(
													"identify-end-no-results",
													returnData);
											}
										});
									} else {
										$scope.$emit("identify-end-no-results",
											returnData);
									}
								});
							break;

						// Update the visibled tiled programs based on the new and old selections.
						case "updateVisibleTiledLayers":
							//in case each selected program has a published tiled service, we create a tiled layer for it
							for (var i = 0; i < data.oscarSelections.length;
								i++) {
								// e.g all|operational
								var pairAsString = data.oscarSelections[i];
								var layerId = 'tiledProgram_' + pairAsString;
								//check if the  layer has already been added to the map.
								if (!$scope.map.getLayer(layerId)) {
									var programAndStatusPairOption = pairAsString.split(
										"_")
                  var url;
                  if (programAndStatusPairOption[2] === "declared") {
                    url = $scope.appProperties.tiledMapServiceUrlPrefix
                        + programAndStatusPairOption[0]
                        + "_declared_"
                        + programAndStatusPairOption[1]
                        + "/MapServer";
                  }
									else {
                    url = $scope.appProperties.tiledMapServiceUrlPrefix
                        + programAndStatusPairOption[0]
                        + "_assessed_"
                        + programAndStatusPairOption[1]
                        + "/MapServer";
                  }
									layer = new esri.layers.ArcGISTiledMapServiceLayer(
										url, {
											id: layerId,
											displayLevels: [0, 1, 2, 3, 4, 5, 6,
												7, 8],
											visible: false,
											copyright: ""
										});
									$scope.addTiledLayer(layer,
										'ArcGISTiledMapServiceLayer');
								}
							}

							// Check the difference between the current selection and the previous one, and REMOVE the unnecessary program layers
							var diff = arr_diff(data.oscarSelections,
								data.oscarSelectionsOld);
							var toHide = []
							// Remove unselected programs
							for (var r = 0; r < diff.length; r++) {
								layerToDelId = 'tiledProgram_' + diff[r];
								//If the layer was already visible, it means we have unselected it
								if ($scope.map.getLayer(layerToDelId) &&
									$scope.map.getLayer(layerToDelId).visible) {
									toHide.push(layerToDelId);
									// TODDO check if needeed
								} else if ($scope.map.getLayer(layerToDelId)) {
									$scope.map.getLayer(layerToDelId).show();
								}
							}
							// Hide the layers in the end to avoid map on/off
							for (var h = 0; h < toHide.length; h++) {
								$scope.map.removeLayer(
									$scope.map.getLayer(toHide[h]));
							}
							break;

						case "updateDynamicServiceExpression":
							console.debug('MAP', $scope.map);
							// Adding a proxy so that we can handle POST requests (if GET request > 2000Chars for large definition expressions)
							require(["esri/request",
									"dojo/_base/json", "esri/config",
									"esri/urlUtils"
								],
								function (esriRequest,
										  JSON,
										  esriConfig,
										  urlUtils,
								) {
									var layer;
									// Show up the layer if not visible
									if ($scope.map.getLayer(data.id) &&
										!$scope.map.getLayer(data.id).visible) {
										$scope.map.getLayer(data.id).show();
									}
									layer = $scope.map.getLayer(data.id);

									// Hide the opposite layer if currently visible
									if ($scope.map.getLayer(data.layerIdToHide) && $scope.map.getLayer(data.layerIdToHide).visible) {
										$scope.map.getLayer(data.layerIdToHide).hide();
									}

									// Valid state: In case we are not in the invalid state when none is selected
									// where a wrong expression is consrtucted
									if ("APPROVAL_STATUS_ID = 1 )" != data.dynamicExpression) {

										// For large dynamic expression pass through proxy, since a POST will automatically be sent by the ArcGIS API
										// NOTE: When length = 406 it starts sending mixed get/Post.
										// We will use roughly 410 as limit for sending passing via proxy expecting post reqs
										if (data.dynamicExpression.length > 410) {
											// Cleanup proxies before adding a new one.
											esriConfig.defaults.io.proxyRules = [];
											// Proxy only the export image queries which might have a large definition expression requiring a POST service call..
											urlUtils.addProxyRule({
												urlPrefix: layer.url + "/export",
												proxyUrl: "rest/api/download/proxydynamic"
											});
										}
										// Cleanup the proxy rules in small definition expression requests
										else {
											esriConfig.defaults.io.proxyRules = [];
										}

										// Apply the definition expression to the layer that should be visible
										var layerDefinitions = [];
										for (var i = 0; i < data.layersNumbers.length; i++) {
											var layerNbr = data.layersNumbers[i];
											layerDefinitions[layerNbr] = data.dynamicExpression;
										}
										$scope.map.getLayer(data.id).setLayerDefinitions(layerDefinitions);
									}
									// Invalid state:  Hide in the invalid state
									else if ("APPROVAL_STATUS_ID = 1 )" == data.dynamicExpression) {
										// Hide if no options are selected for programs or statuses. This is an invalid state when no options are selected
										$scope.map.getLayer(data.id).hide();
									}
								});
							break;


						case "clearLayerGraphics":
							if ($scope.map.getLayer(data.id)) {
								$scope.map.getLayer(data.id).clear();
							}
							break;

						case "setDefinitionExpression":
              if ($scope.map.getLayer(data.id)) {
                $scope.map.getLayer(data.id).setDefinitionExpression(data.args);
              }
							break;

						case "performGeoprocessorCall":
							if ($scope.map.getLayer(data.id)) {
								require(["esri/tasks/Geoprocessor",
										"esri/geometry/webMercatorUtils"],
									function (Geoprocessor, webMercatorUtils) {
										var gp = new Geoprocessor(
											data.args.url);
										//TODO retrieve the WKid from the map so as the returned wkid to conform with every map
										gp.setOutSpatialReference({
											wkid: 102100
										});
										var gparams = data.args.gparams
										gp.execute(gparams);
										gp.on("execute-complete", function (d) {
											var featureSet = d.results[0].value;
											for (var i = 0;
												i < featureSet.features.length;
												i++) {
												var featureGraphic = featureSet.features[i];
												//Fix the projection of graphics returned from the GP service, so as to have the mercator srid: 102100, just like the basemap
												//featureGraphic.geometry=webMercatorUtils.geographicToWebMercator(featureGraphic.geometry)
												$scope.map.getLayer(
													data.id).add(
													featureGraphic);
											}
											$scope.$emit(data.id
												+ "-service-container-drawn",
												data);
										});
									});
							} else {
								Application.debugLogger(
									'The Graphic layer required does not exist');
								throw new Error(
									"The Graphic layer required does not exist.");
							}
							break;

						case "addGraphicsToTheMap":
							if ($scope.map.getLayer(data.id)) {
								require(["esri/geometry/webMercatorUtils",
										"esri/geometry/Geometry",
										"esri/tasks/FeatureSet"],
									function (webMercatorUtils, Geometry,
										FeatureSet) {
										var stationData = data.args
										var featureSet = new FeatureSet()
										featureSet.fields = [{
											"name": "STATION_NAME",
											"type": "esriFieldTypeString",
											"alias": "STATION_NAME",
											"length": 50
										}];
										featureSet.features = stationData;
										var addedGraphics = [];
										for (var i = 0;
											i < featureSet.features.length;
											i++) {
											var featureGraphic = featureSet.features[i];
											// TODO REPROJECT ON THE FLY FOR ANY PROJECTION
											//https://geonet.esri.com/groups/geodev/blog/2014/11/03/use-proj4js-alongside-the-arcgis-api-for-javascript-to-reproject-coordinates-on-the-fly
											// Add graphics only once
											if (!(addedGraphics[featureGraphic.attributes.STATION_ID]
												&& addedGraphics[featureGraphic.attributes.STATION_ID]
												== 1)) {
												featureGraphic.geometry = esri.geometry.geographicToWebMercator(
													featureGraphic.geometry);
												$scope.map.getLayer(
													data.id).add(
													featureGraphic);
												addedGraphics[featureGraphic.attributes.STATION_ID] = "1";
											}
										}
										$scope.map.setZoom(2);
										$scope.$emit(
											data.id + "-graphics-layer-drawn",
											data);
									});
							} else {
								throw new Error(
									"The Graphic layer required does not exist.");
							}
							break;

						case "addQueryTaskGraphicsToTheMap":
							if ($scope.map.getLayer(data.layerId)) {
								require(["esri/geometry/webMercatorUtils",
										"esri/geometry/Geometry",
										"esri/tasks/FeatureSet", "esri/tasks/query",
										"esri/tasks/QueryTask"],
									function (webMercatorUtils, Geometry,
										FeatureSet, Query, QueryTask) {
										var query = new Query();
										var queryTask = new QueryTask(
											data.queryUrl);
										query.where = data.queryExpression;
										query.outSpatialReference = {
											wkid: 102100
										};
										query.returnGeometry = true;
										query.outFields = ["*"];

										queryTask.execute(query,
											function (result) {
												var addedGraphics = [];
												angular.forEach(result.features,
													function (featureGraphic) {
														if (data.applyLargeSymbology
															== "true") {
															featureGraphic.attributes.STATUS_CD += ' Large'
														}

														// ADD only once in the map
														if (!(addedGraphics[featureGraphic.attributes.STATION_ID]
															&& addedGraphics[featureGraphic.attributes.STATION_ID]
															== 1)) {
															$scope.map.getLayer(
																data.layerId).add(
																featureGraphic);
															addedGraphics[featureGraphic.attributes.STATION_ID] = "1";
														}
													});
												$scope.map.getLayer(
													data.layerId).refresh();
												$scope.$emit(data.layerId
													+ "-graphics-layer-drawn",
													data);
											});

									});
							}
							break;

						case "addOneGraphicToTheMap":
							if ($scope.map.getLayer(data.id)) {
								require(["esri/geometry/webMercatorUtils",
										"esri/geometry/Geometry"],
									function (webMercatorUtils, Geometry) {
										var graphic = data.graphic
										// TODO REPROJECT ON THE FLY FOR ANY PROJECTION
										//https://geonet.esri.com/groups/geodev/blog/2014/11/03/use-proj4js-alongside-the-arcgis-api-for-javascript-to-reproject-coordinates-on-the-fly
										$scope.map.getLayer(data.id).add(
											graphic);
										$scope.$emit(
											data.id + "-graphics-layer-drawn",
											data);
									});
							} else {
								throw new Error(
									"The Graphic layer required does not exist.");
							}
							break;

						case "fitExtentToCurrentGraphics":
							require(["dojo/_base/array"],
								function (arrayUtils) {
									var allGraphics = [];
									arrayUtils.forEach(
										$scope.map.graphicsLayerIds,
										function (graphicsLayerId) {
											allGraphics = allGraphics.concat(
												$scope.map.getLayer(
													graphicsLayerId).graphics);
										});
									if (allGraphics.length > 1) {
										// 	Bug 15248:
										// In case there are multiple stations the extent should expand,
										// so as to avoid hidden dot behind the copyright.
										var myFeatureExtent = esri.graphicsExtent(
											allGraphics).expand(2);
										$scope.map.setExtent(myFeatureExtent,
											true);
									} else {
										if (allGraphics[0]) {
											if (allGraphics[0].geometry) {
												$scope.map.centerAndZoom(
													allGraphics[0].geometry, 7);
											}
										} else {
											Application.debugLogger(
												'There are no graphics to fit extent');
											console.debug(
												'There are no graphics to fit extent');
										}
									}
								});
							break;

						case "fitExtentToLayerGraphics":
							fitExtentToLayerGraphics(data);
							break;

						case "highlightLayerGraphic":
							require(["dojo/_base/array"],
								function (arrayUtils) {
									var allGraphics = [];
									allGraphics = allGraphics.concat(
										$scope.map.getLayer(
											data.layerId).graphics);
									var hightlightObj = {};
									for (var i = 0; i < allGraphics.length;
										i++) {
										var graphic = allGraphics[i];
										if (graphic.attributes.STATION_ID
											== data.graphicId) {

											// Use the fixed symbology for the large elements
											if (data.renderer && data.renderer
												== "useLargeSymbols") {
												graphic.attributes.STATUS_CD = graphic.attributes.STATUS_CD
													+ CONSTANTS.MAP_LARGE_SYMBOLOGY_SUFFIX
												hightlightObj.graphic = graphic
												// Reset the highlighed feature to its original state
												if (data.oldHighlightedFeature
													!= null
													&& data.oldHighlightedFeature.graphic) {
													// Removes the CONSTANTS.MAP_LARGE_SYMBOLOGY_SUFFIX suffix
													var nbrOfCharsToRemove = CONSTANTS.MAP_LARGE_SYMBOLOGY_SUFFIX.length
													data.oldHighlightedFeature.graphic.attributes.STATUS_CD = data.oldHighlightedFeature.graphic.attributes.STATUS_CD.slice(
														0, -nbrOfCharsToRemove);
												}
											}
											// Enlarging the existing images of the render
											else {
												var originalSymbol = angular.copy(
													$scope.map.getLayer(
														data.layerId).renderer.getSymbol(
														graphic));
												hightlightObj.originalSymbol = originalSymbol;
												// Reset the highlighed feature to its original state
												if (data.oldHighlightedFeature
													!= null
													&& data.oldHighlightedFeature.graphic) {
													data.oldHighlightedFeature.graphic.symbol = data.oldHighlightedFeature.originalSymbol;
												}
												var higlightedSymbol = angular.copy(
													$scope.map.getLayer(
														data.layerId).renderer.getSymbol(
														graphic));
												higlightedSymbol.height = higlightedSymbol.height
													* 2
												higlightedSymbol.width = higlightedSymbol.width
													* 2
												hightlightObj.higlightedSymbol = higlightedSymbol;
												graphic.symbol = higlightedSymbol;
												hightlightObj.graphic = graphic;
											}
											break;
										} // end if
									} // end for

									// By default pan the map to the selected point
									if (hightlightObj && hightlightObj.graphic
										&& hightlightObj.graphic.geometry) {
										$scope.map.centerAndZoom(
											hightlightObj.graphic.geometry,
											$scope.map.getZoom());
									} else {
										alert(
											"The specific station cannot be projected on the map. Possible reasons: north-south pole station. ")
									}
									// Emit event that the highlight has been completed
									$scope.map.getLayer(data.layerId).refresh();
									$scope.$emit(data.layerId + "-onhighlight",
										hightlightObj);
									// Fit extent to layer graphics again if required
									if (data.fitToLayerExtent != null
										&& data.fitToLayerExtent != "none") {
										var fitArgs = {
											layerId: data.fitToLayerExtent
										}
										fitExtentToLayerGraphics(fitArgs)
									}
									// Focus on map if required
									if (data.focusOnMap && data.focusOnMap
										== "true") {
										$location.hash($scope.map.id);
										$anchorScroll();
									}

								});
							break;

						case "centerAndZoom":
							if (data.graphic.geometry) {
								$scope.map.centerAndZoom(data.graphic.geometry,
									data.zoomLevel);
							} else {
								Application.debugLogger(
									"no geometry found to zoom in");
							}
							break;

						case "initializeInfobox":
							//Initialize the dijit popoup
							var widget = dijit.byId("tooltipDialog");
							if (widget) {
								widget.destroy();
							}
							tooltipDialog = new dijit.TooltipDialog({
								id: "tooltipDialog",
								style: "position: absolute; width: 200px; font: normal normal normal 10pt Helvetica;z-index:100000; opacity:1; border:none"
							});
							tooltipDialog.startup();
							break;

						case "showInfobox":
							openInfobox(data);
							break;

						case "closeInfobox":
							dijit.popup.close(tooltipDialog);
							break;

						case "resizeMap":
							resizeMap(data);
							break;

						case "applyGraphicsLayerScaleDependentRenderer":
							applyGraphicsLayerScaleDependentRenderer(data);
							break;

					}
				} //end map do functions
			}; //END OF MAP INIT FUNCTION

			// #######################		MAP HANDLING UTIL FUNCTIONS #######################

			// Apply a renderer based on the zoom level, for the provided layer.
			// This is a custom functionality to support scale dependent renderer for graphics layers since it
			// is not supported out of the box by esri;  https://community.esri.com/thread/50705.
			var applyGraphicsLayerScaleDependentRenderer = function (data) {
				var glayer = $scope.map.getLayer(data.layerId);
				if (glayer.rendererList) {
					var zoom = $scope.map.getZoom();
					for (var i = 0; i< glayer.rendererList.length; i++) {
						var rendererInfo = glayer.rendererList[i];
						if (zoom >= rendererInfo.minZoom && zoom <= rendererInfo.maxZoom &&
							glayer.renderer != rendererInfo.renderer) {
							glayer.setRenderer(rendererInfo.renderer)
							glayer.refresh()
							break;
						}
					}
				}
			}

			//find the different elemenets between two arrays
			function arr_diff(a1, a2) {
				var a = [],
					diff = [];
				for (var i = 0; i < a1.length; i++) {
					a[a1[i]] = true;
				}
				for (var i = 0; i < a2.length; i++) {
					if (a[a2[i]]) {
						delete a[a2[i]];
					} else {
						a[a2[i]] = true;
					}
				}
				for (var k in a) {
					diff.push(k);
				}
				return diff;
			}

			var openInfobox = function (data) {
				if (data.clickedFeature) {
					var content = $("#map1-infobox").html()
					tooltipDialog.setContent(content);

					dijit.popup.open({
						popup: tooltipDialog,
						x: data.clickedFeature.pageX,
						y: data.clickedFeature.pageY
					});

					//Fix the positioning of infobox
					var TOP_OFFSET = 10;
					var LEFT_OFFSET = 10;
					if ($(".dijitTooltipDialog").hasClass(
						"dijitTooltipBelow")) {
						$(".dijitPopup").animate({
							top: "+=10"
						}, 0);
					}
					//Above
					else {
						$(".dijitPopup").animate({
							top: "-=10"
						}, 0);
					}
					//Right
					if ($(".dijitTooltipDialog").hasClass(
						"dijitTooltipABRight")) {
						$(".dijitPopup").animate({
							left: "-=10"
						}, 0);
					}
					//Left
					else {
						$(".dijitPopup").animate({
							left: "+=10"
						}, 0);
					}
				}
			}

			// Called ONLY after resizing
			var setValidExtent = function (oldExtent, map) {
				var MAX_Y = 20000000;
				// use a buffer so as not to be affected by small distances
				var BUFFER = 0;
				if (!(oldExtent.ymax > MAX_Y && oldExtent.ymin < -MAX_Y)) {
					if (oldExtent.ymax > MAX_Y + BUFFER) {
						var calcExtent = angular.copy(oldExtent)
						if (map.getZoom() == 1) {
							calcExtent.ymax = MAX_Y;
							calcExtent.ymin = -MAX_Y;
							$scope.validExtent = calcExtent;
							map.setExtent(calcExtent, false);
						} else {
							// calculate a valid extent
							var yDiff = Math.abs(oldExtent.ymax) - MAX_Y;
							// shift ymin/ymax to a diff so as to be valid
							calcExtent.ymin = calcExtent.ymin - yDiff;
							calcExtent.ymax = MAX_Y;
							Application.debugLogger(
								'1) oldExtent.ymax > MAX_Y + BUFFER', oldExtent)
							$scope.validExtent = calcExtent;
							map.setExtent(calcExtent, false);
						}
					} else if (oldExtent.ymin < -(MAX_Y + BUFFER)) {
						// calculate a valid extent
						var calcExtent = oldExtent;
						// show map always on top
						if (map.getZoom() == 1) {
							calcExtent.ymax = MAX_Y;
							calcExtent.ymin = -MAX_Y;
							$scope.validExtent = calcExtent;
							map.setExtent(calcExtent, false);
						} else {
							Application.debugLogger(
								'2) oldExtent.ymax > MAX_Y + BUFFER',
								oldExtent);
							var yDiff = Math.abs(oldExtent.ymin) - MAX_Y;
							// shift ymin/ymax to a diff so as to be valid
							calcExtent.ymin = calcExtent.ymin + yDiff;
							calcExtent.ymax = calcExtent.ymax + yDiff;
							$scope.validExtent = calcExtent;
							map.setExtent(calcExtent, false);
						}
					}
				} else {
					Application.debugLogger(
						'3) ELSE: oldExtent.ymax > MAX_Y && oldExtent.ymin < -MAX_Y',
						oldExtent)
					var calcExtent = oldExtent;
					calcExtent.ymax = MAX_Y;
					calcExtent.ymin = -MAX_Y;
					map.setExtent(calcExtent, false);
				}
			}

			//resizes the map according to a specific height
			var resizeMap = function (data) {
				if (data.height) {
					$('#' + data.mapDivID).css({
						"height": data.height + "px"
					});
				}
				if (data.width) {
					$('#' + data.mapDivID).css({
						"width": data.width + "px"
					});
				}
				var resizeTimer;
				clearTimeout(resizeTimer);
				//Center the map after 600ms so as the map to have finished resizing
				resizeTimer = setTimeout(function () {
					$scope.map.resize();
					$scope.map.reposition();
				}, 600);
			}

			var fitExtentToLayerGraphics = function (data) {
				require(["dojo/_base/array"],
					function (arrayUtils) {
						var allGraphics = [];
						allGraphics = allGraphics.concat(
							$scope.map.getLayer(data.layerId).graphics);
						// used in station report to zoom to the station geometry, in case the arcgis returns many stations since it is owned by many diffrent programs
						if (data.fitToFirstElement == 'true') {
							if (allGraphics.length > 0 && allGraphics[0]
								&& allGraphics[0].geometry) {
								Application.debugLogger(
									"zoom to first graphic allGraphics[0]:",
									allGraphics[0]);
								$scope.map.centerAndZoom(
									allGraphics[0].geometry, 7);
							} else {
								Application.debugLogger(
									"There is no first graphic:");
							}
						} else if (allGraphics.length > 1) {
							// 	Bug 15248:
							// In case there are multiple stations the extent should expand,
							// so as to avoid hidden dot behind the copyright.
							var myFeatureExtent = esri.graphicsExtent(
								allGraphics).expand(2);
							$scope.map.setExtent(myFeatureExtent, true);
						} else {
							Application.debugLogger(
								"NOT  allGraphics.length > 1:");
							if (allGraphics[0]) {
								if (allGraphics[0].geometry) {
									$scope.map.centerAndZoom(
										allGraphics[0].geometry, 7);
								}
							} else {
								Application.debugLogger(
									"There are no graphics to fit extent");
							}
						}
						applyGraphicsLayerScaleDependentRenderer(data)

					});
			}

			// ####################### FUNCTIONS FOR CREATING LAYERS - CALLED BY DIRECVES #######################
			/*
			 * Add-Layer functions which place a  specific layer on the map
			 * The functions are called from inside the directives
			 *
			 * */
			$scope.addTiledLayer = function (layer, layerType) {
				if (layerType == 'ArcGISTiledMapServiceLayer') {
					require(["dojo/on"], function (on) {
						layer.on("update-end", function (e, d) {
							$scope.$emit(layer.id + "-update-end", e, d);
						});
					});
				}
				if ($scope.map) {
					$scope.map.addLayer(layer);
					Application.debugLogger("add tiled layer ", layer);
				} else {
					tiledLayers.push(layer);
				}
			}

			$scope.addFeatureLayer = function (layer, options) {
				// If we already have a map, add the layer directly to the existing map,
				// otherwise push it into an array for the map to fetch it from once
				// initialised.
				// Attach events to this layer.
				require(["dojo/on"], function (on) {
					if (options.clickable == "true") {
						on(layer, "click", function (e, d) {
							$scope.$emit(layer.id + "-onclick", e, d);
						});
					}
					if (options.overable == "true") {
						on(layer, "mouse-over", function (e, d) {
							$scope.$emit(layer.id + "-onmouseover", e, d);
							$scope.map.setMapCursor("pointer");
						});

						on(layer, "mouse-move", function (e, d) {
							$scope.$emit(layer.id + "-onmousemove", e, d);
							$scope.map.setMapCursor("pointer");
						});

						on(layer, "mouse-out", function (e, d) {
							$scope.$emit(layer.id + "-onmouseout", e, d);
							$scope.map.setMapCursor("default");
						});
					}
					if (options.watched == "true") {
						layer.on("update-end", function (e, d) {
							$scope.$emit(layer.id + "-update-end", e, d);

						});

					}
				});

				if ($scope.map) {
					$scope.map.addLayer(layer);
				} else {
					featureLayers.push(layer);
				}
			};

			$scope.addDynamicLayer = function (layer, options) {
				// If we already have a map, add the layer directly to the existing map,
				// otherwise push it into an array for the map to fetch it from once
				// initialised.
				// Attach events to this layer.
					if (options.clickable == "true") {
						on(layer, "click", function (e, d) {
							$scope.$emit(layer.id + "-onclick", e, d);
						});
					}
					if (options.watched == "true") {
						layer.on("map-image-export", function (e) {
							$scope.$emit(layer.id + "-map-image-export", e,
								layer.graphics);
						});
						layer.on("update-end", function (e, d) {
							$scope.$emit(layer.id + "-update-end", e, d);
						});
					}
				if ($scope.map) {
					$scope.map.addLayer(layer);
				} else {
					dynamicLayers.push(layer);
				}
			};

			$scope.addGraphicsLayer = function (layer, options, attrs) {
				// Attach events to this layer.
				require(["dojo/on"], function (on) {
					if (options.overable == "true") {
						on(layer, "click", function (e, d) {
							$scope.$emit(layer.id + "-onclick", e, d);
						});
					}
					if (options.clickable == "true") {
						on(layer, "mouse-over", function (e, d) {
							$scope.$emit(layer.id + "-onmouseover", e, d);
							$scope.map.setMapCursor("pointer");
						});
						on(layer, "mouse-out", function (e, d) {
							$scope.$emit(layer.id + "-onmouseout", e, d);
							$scope.map.setMapCursor("default");
						});
					}
					if (options.watched == "true") {
						layer.on("update-end", function (e) {
							$scope.$emit(layer.id + "-update-end", e,
								layer.graphics);
						});
					}
				});

				// If we already have a map, add the layer is add  directly to the existing map,
				// otherwise push it into an array for the map to fetch it from once initialised.
				if ($scope.map) {
					$scope.map.addLayer(layer);
					if (attrs.gpurl) {
						//Emit event that a layer which depends on service call (Geoprocessor, QueryTask etc has been loaded)
						$scope.$emit(layer.id + "-service-container-load",
							attrs.gpurl);
					} else {
						//If we dont have a simple graphics layer without geoprocessing service
						$scope.$emit(layer.id + "-graphics-layer-load");

					}
				} else {
					var glayerObject = {
						"layer": layer,
						"gpurl": attrs.gpurl
					}
					graphicsLayers.push(glayerObject);
				}
			}; //end of addGraphicsLayer
		}
	]) //end of controller

// ####################### DIRECTIVES DEFINITION #######################
.directive("esriMap", function () {
	return {
		restrict: "EA",
		controller: "ESRIMapController",
		scope: true,
		link: function (scope, elem, attr, ctrl) {
			ctrl.init(elem);
		}
	}
})

.directive("dynamicLayer", function () {
	return {
		restrict: "EA",
		scope: true,
		link: function (scope, elem, attrs, ctrl) {
			if (!attrs.id) {
				throw new Error("An id is required for a dynamic layer.");
			}
			if (!attrs.url) {
				throw new Error("A url is required for a dynamic layer.");
			}
			require(["esri/layers/ArcGISDynamicMapServiceLayer",
					"esri/layers/ImageParameters",
					"esri/layers/LayerDrawingOptions",
					"esri/renderers/SimpleRenderer",
					"esri/symbols/SimpleMarkerSymbol",
					"esri/symbols/SimpleLineSymbol"
				],
				function (ArcGISDynamicMapServiceLayer, ImageParameters,
					LayerDrawingOptions, SimpleRenderer, SimpleMarkerSymbol,
					SimpleLineSymbol) {
					var layerOpts = {
						id: attrs.id,
						outFields: attrs.fields ? attrs.fields : "*",
						opacity: attrs.opacity ? Number(attrs.opacity) : 1,
						disableClientCaching: false,
						// Set the scale range for the layer.  If minScale and maxScale are set to 0 then the layer will be visible at all scales.
						minScale: attrs.minScale ? Number(attrs.minScale) : 0,

					}
					layerOpts.visible = true
					if (attrs.visible == "false") {
						layerOpts.visible = false
					}
					//ImageParameters.layerDefinitions takes an array.  The index of the array corresponds to the layer id.
					//In the sample below an element is added in the array at 3, 4, and 5 indexes.
					//Those array elements correspond to the layer id within the remote ArcGISDynamicMapServiceLayer
					var layerDefs = [];
					var expression =  attrs.expression;

					var imageParameters = new ImageParameters();
					if (attrs.layerNumbers) {
						var layerNumbersArr = attrs.layerNumbers.split(",");
						imageParameters.layerIds = [];
						for (var i = 0; i < layerNumbersArr.length; i++) {
							layerDefs[layerNumbersArr[i]] = expression;
							imageParameters.layerIds.push(layerNumbersArr[i]);
						}
					}

					//Use the ImageParameters to set map service layer definitions and map service visible layers before adding to the client map.
					imageParameters.layerDefinitions = layerDefs;
					imageParameters.layerOption = ImageParameters.LAYER_OPTION_SHOW;
					imageParameters.transparent = true;
					layerOpts.imageParameters = imageParameters;

					var layer = new ArcGISDynamicMapServiceLayer(attrs.url,
						layerOpts);
					layer.setImageFormat("png32")

					var options = {
						clickable: attrs.clickable,
						overable: attrs.overable,
						watched: attrs.watched
					};
					scope.addDynamicLayer(layer, options);
				});
		}
	}
})

.directive("featureLayer", function () {
	return {
		restrict: "EA",
		scope: true,
		link: function (scope, elem, attrs, ctrl) {
			if (!attrs.id) {
				throw new Error("An id is required for a feature layer.");
			}
			if (!attrs.url) {
				throw new Error("A url is required for a feature layer.");
			}
			require(["esri/layers/FeatureLayer",
				"esri/symbols/SimpleMarkerSymbol",
				"esri/symbols/SimpleLineSymbol"
			], function (FeatureLayer, SimpleMarkerSymbol, SimpleLineSymbol) {
				var layerOpts = {
					id: attrs.id,
					mode: FeatureLayer.MODE_SNAPSHOT,
					outFields: attrs.fields ? attrs.fields : "*",
					opacity: attrs.opacity ? Number(attrs.opacity) : 1
				}
				// If a definition expression has not been set do not include it in the layer options
				// since an empty definition expression causes an error when attempting to retrieve the layer.
				if (attrs.definitionexpression) {
					layerOpts.definitionExpression = attrs.definitionexpression;
				}
				var layer = new FeatureLayer(attrs.url, layerOpts);
				/*Create a renderer for oscar layer */
				if (attrs.customRenderer == 'true') {
					var SYMBOLS_SIZE = 4;
					if (attrs.symbolsize) {
						SYMBOLS_SIZE = Number(attrs.symbolsize);
					}
					var symbol = new SimpleMarkerSymbol(
						SimpleMarkerSymbol.STYLE_CIRCLE,
						SYMBOLS_SIZE,
						new SimpleLineSymbol(
							SimpleLineSymbol.STYLE_NULL,
							new dojo.Color([14, 113, 188, 1]),
							1
						),
						new dojo.Color([14, 113, 188, 1])
					);
					var myRenderer = new esri.renderer.SimpleRenderer(symbol);
					layer.setRenderer(myRenderer);
				}

				if (attrs.zeroSyblolSize == 'true') {
					var symbol = new esri.symbol.SimpleMarkerSymbol();
					symbol.setColor(new dojo.Color([14, 113, 188]));
					symbol.setSize("0");
					var myRenderer = new esri.renderer.SimpleRenderer(symbol);
					layer.setRenderer(myRenderer);
				}
				var options = {
					clickable: attrs.clickable,
					overable: attrs.overable,
					watched: attrs.watched
				};
				scope.addFeatureLayer(layer, options);
			});
		}
	}
})

.directive("geoprocessorFeatures", function () {
	return {
		restrict: "EA",
		scope: true,

		link: function (scope, elem, attrs, ctrl) {
			if (!attrs.id) {
				throw new Error("An id is required for geoprocessor features");
			}
			if (!attrs.gpurl) {
				throw new Error(
					"A geoprocessing url (gpurl) is required for geoprocessor");
			}
			require([
				"esri/layers/GraphicsLayer",
				"esri/symbols/SimpleMarkerSymbol",
				"esri/renderers/SimpleRenderer",
				"dojo/on",
				"esri/symbols/SimpleLineSymbol"
			], function (
				GraphicsLayer,
				SimpleMarkerSymbol,
				SimpleRenderer,
				on,
				SimpleLineSymbol
			) {
				var layer = new GraphicsLayer({
					id: attrs.id,
					opacity: 0.3
				});

				//Check if we have a renderer url, which means we want to rereieve the renderer from an already published feature layer
				if (attrs.rendererurl) {
					var tmpFlayer = new esri.layers.FeatureLayer(
						attrs.rendererurl, {
							id: 'tmpLayer',
							outFields: "*"
						});
					on(tmpFlayer, "load", function (e, d) {
						layer.setRenderer(e.layer.renderer);
					});
				} else if (attrs.customRenderer == 'true') {
					var SYMBOLS_SIZE = 4
					var symbol = new SimpleMarkerSymbol(
						SimpleMarkerSymbol.STYLE_CIRCLE,
						SYMBOLS_SIZE,
						new SimpleLineSymbol(
							SimpleLineSymbol.STYLE_NULL,
							new dojo.Color([14, 113, 188, 1]),
							1
						),
						new dojo.Color([14, 113, 188, 1])
					);
					var myRenderer = new esri.renderer.SimpleRenderer(symbol);
					layer.setRenderer(myRenderer);
				}
				var options = {
					clickable: attrs.clickable,
					overable: attrs.overable,
					watched: attrs.watched
				};
				// The attr argument will contain the gpUrl which
				//identifies whether a graphics Layer is a layer
				//that is built from a geoprocessing service
				scope.addGraphicsLayer(layer, options, attrs);
			});
		}
	}
})

.directive("graphicsLayer", function () {
	return {
		restrict: "EA",
		scope: true,
		link: function (scope, elem, attrs, ctrl) {
			if (!attrs.id) {
				throw new Error("An id is required for graphics layer");
			}
			require([
				"esri/layers/GraphicsLayer",
				"esri/symbols/SimpleMarkerSymbol",
				"esri/renderers/SimpleRenderer",
				"dojo/on",
				"esri/symbols/SimpleLineSymbol",
				"esri/renderers/ScaleDependentRenderer",
				"esri/renderers/UniqueValueRenderer"

			], function (
				GraphicsLayer,
				SimpleMarkerSymbol,
				SimpleRenderer,
				on,
				SimpleLineSymbol,
				ScaleDependentRenderer,
				UniqueValueRenderer) {

				var layer = new GraphicsLayer({
					id: attrs.id
				});

				// Layer options
				var options = {
					clickable: attrs.clickable,
					overable: attrs.overable,
					watched: attrs.watched
				};

				//Check if we have a renderer url, which means we want to retrieve the renderer from an already published feature layer
				if (attrs.rendererurl && attrs.scaledependentrenderer
					&& Boolean(attrs.scaledependentrenderer) == true) {
					// Create temp feature layers based on the renderer url, so as to assemble a scale dependent
					// renderer from the renderers of all the layers of the map service.
					var s = attrs.rendererurl;
					var tmpFlayer = new esri.layers.FeatureLayer(s, {
						id: 'tmpLayer',
						outFields: "*"
					});
					var nextNbr = Number(s.substring(s.lastIndexOf('/') + 1))
						+ 1
					s = s.replace(/\/[^\/]*$/, '/' + nextNbr)
					var tmpFlayer2 = new esri.layers.FeatureLayer(s, {
						id: 'tmpLayer',
						outFields: "*"
					});

					nextNbr = Number(s.substring(s.lastIndexOf('/') + 1)) + 1
					s = s.replace(/\/[^\/]*$/, '/' + nextNbr)
					var tmpFlayer3 = new esri.layers.FeatureLayer(s, {
						id: 'tmpLayer',
						outFields: "*"
					});

					var rendererList = [];


					// on load of te first layer initialize the scale dependent renderer.
					on(tmpFlayer, "load", function (e1, d1) {
						on(tmpFlayer2, "load", function (e2, d2) {
							on(tmpFlayer3, "load", function (e3, d3) {
								rendererList =  [
									{
										"renderer": e1.layer.renderer,
										"minZoom": 0,
										"maxZoom": 5
									},
									{
										"renderer": e2.layer.renderer,
										"minZoom": 6,
										"maxZoom": 8
									},
									{
										"renderer": e3.layer.renderer,
										"minZoom": 9,
										"maxZoom": 16
									}
									];
								layer.rendererList = rendererList;
								// set renderer1 as a default until it is readjusted based on the zoom level
								layer.setRenderer(rendererList[0].renderer);
								// The attr argument will contain the gpUrl which
								//identifies whether a graphics Layer is a layer
								//that is built from a geoprocessing service
								scope.addGraphicsLayer(layer, options, attrs);
							}); // end on load tmpFlayer3
						}); // end on load tmpFlayer2
					}); // end on load tmpFlayer
				}// end if scale dependent Renderer

					// Use a one specific renderer without scale dependency.
				else if (attrs.rendererurl) {
					var tmpFlayer = new esri.layers.FeatureLayer(
						attrs.rendererurl, {
							id: 'tmpLayer',
							outFields: "*"
						});
					on(tmpFlayer, "load", function (e, d) {
						layer.setRenderer(e.layer.renderer);
						// The attr argument will contain the gpUrl which
						//identifies whether a graphics Layer is a layer
						//that is built from a geoprocessing service
						scope.addGraphicsLayer(layer, options, attrs);
					});
				}

				// Custom renderent created in the client side.
				else if (attrs.customRenderer == 'true') {
					var SYMBOLS_SIZE = 4;
					var symbol = new SimpleMarkerSymbol(
						SimpleMarkerSymbol.STYLE_CIRCLE,
						SYMBOLS_SIZE,
						new SimpleLineSymbol(
							SimpleLineSymbol.STYLE_NULL,
							new dojo.Color([14, 113, 188, 1]),
							1
						),
						new dojo.Color([14, 113, 188, 1])
					);
					var myRenderer = new esri.renderer.SimpleRenderer(symbol);
					layer.setRenderer(myRenderer);
					// The attr argument will contain the gpUrl which
					//identifies whether a graphics Layer is a layer
					//that is built from a geoprocessing service
					scope.addGraphicsLayer(layer, options, attrs);
				}

			});
		}
	}
})

.directive("tiledLayer", function () {
	return {
		restrict: "EA",
		scope: true,
		link: function (scope, elem, attrs, ctrl) {
			if (!attrs.id) {
				throw new Error("An id is required for a tiled layer.");
			}
			if (!attrs.url) {
				throw new Error("A url is required for a tiled layer.");
			}
			var layer;
			if (attrs.arcgisTiledLayer != "true") {
				require(["esri/layers/WebTiledLayer"],
					function (WebTiledLayer) {
						layer = new WebTiledLayer(
							attrs.url.replace('{z}/{x}/{y}',
								'${level}/${col}/${row}'), {
								copyright: attrs.copyright ? attrs.copyright
									: "",
								id: attrs.id
							});
						scope.addTiledLayer(layer, 'WebTiledLayer');
					});
			} else {
				require(["esri/layers/ArcGISTiledMapServiceLayer"],
					function (ArcGISTiledMapServiceLayer) {
						layer = new ArcGISTiledMapServiceLayer(attrs.url, {
							id: attrs.id,
							displayLevels: [0, 1, 2, 3, 4, 5, 6, 7, 8],
							opacity: attrs.opacity ? Number(attrs.opacity) : 1,
							copyright: attrs.copyright ? attrs.copyright : ""
						});
						scope.addTiledLayer(layer,
							'ArcGISTiledMapServiceLayer');
					});
			}
		}
	}
});

